using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
namespace Underwater.Editor {
public static class DolphinStallAudit {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity";
 public static bool Baseline;public static void Run(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory("Renders/UserDolphinIssue");var actors=UnityEngine.Object.FindObjectsByType<WreckCreature>(FindObjectsSortMode.None).Where(a=>a.species==WreckCreature.Species.Dolphin).OrderBy(a=>a.name).ToArray();if(Baseline)foreach(var a in actors)a.GetComponent<DolphinSwimController>().recoveryDelay=float.PositiveInfinity;var stalled=new float[3];var log=new System.Text.StringBuilder();var distance=new float[3];var forwardDistance=new float[3];float longest=0;
 for(int f=0;f<24000;f++)for(int i=0;i<3;i++){var a=actors[i];var before=a.GetComponent<ReefSphereBody>().WorldCenter;var viewer=a.habitatCenter+new Vector3(3,.1f,3);a.Step(.05f,viewer);a.GetComponent<ReefAnimalClearance>().Enforce();Physics.SyncTransforms();float moved=(a.GetComponent<ReefSphereBody>().WorldCenter-before).magnitude;if(!a.GetComponent<ReefSphereBody>().Clear(a.transform.position))throw new Exception("Dolphin body overlaps reef");distance[i]+=moved;forwardDistance[i]+=Mathf.Max(0,Vector3.Dot(a.GetComponent<ReefSphereBody>().WorldCenter-before,a.transform.forward));stalled[i]=moved<.005f*.05f?stalled[i]+.05f:0;longest=Mathf.Max(longest,stalled[i]);if(stalled[i]>(Baseline?2:8)){var body=a.GetComponent<ReefSphereBody>();var d=a.GetComponent<DolphinSwimController>();log.AppendLine(a.name+" stalled after "+f*.05f+" s, pos="+a.transform.position+" forward="+a.transform.forward+" clear="+body.Clear(a.transform.position)+" speed="+d.ActualSpeed+" turnLift="+d.RequiredTurnLift+" rotationBlocked="+d.RotationBlocked+" recoveries="+d.ClearanceRecoveries+" yaw="+typeof(DolphinSwimController).GetField("yawVelocity",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(d));foreach(var c in Physics.OverlapSphere(body.WorldCenter,body.radius+.15f,1<<8,QueryTriggerInteraction.Ignore))log.AppendLine("Nearby solid "+c.name+" gap="+(Vector3.Distance(body.WorldCenter,c.ClosestPoint(body.WorldCenter))-body.radius));File.WriteAllText("Renders/UserDolphinIssue/StallAudit.txt",log.ToString());Debug.Log("DOLPHIN_STALL_REPRODUCED\n"+log);if(Baseline)return;throw new Exception("Sustained dolphin stall");}}
 if(!Baseline&&forwardDistance.Any(d=>d<600))throw new Exception("Recovery is masking a lack of forward progress");log.AppendLine("Forward progress="+string.Join(",",forwardDistance)+"; recoveries="+string.Join(",",actors.Select(a=>a.GetComponent<DolphinSwimController>().ClearanceRecoveries)));log.AppendLine("20-minute simulation completed without sustained stall. Travel="+string.Join(",",distance)+"; longest near-zero-motion interval="+longest+" s");File.WriteAllText("Renders/UserDolphinIssue/StallAudit.txt",log.ToString());Debug.Log(log);}
 public static void CompleteProof(){Baseline=true;Run();File.Copy("Renders/UserDolphinIssue/StallAudit.txt","Renders/UserDolphinIssue/BaselineStall.txt",true);Baseline=false;Run();DolphinLiveSyncCheck.Run();}
}
}





